package com.example.service;

import com.example.dto.ChatRequest;
import com.example.dto.ChatResponse;

/**
 * RAG chat service. Orchestrates question embedding, similarity search,
 * context building, and LLM generation.
 */
public interface ChatService {

    /**
     * Processes a user question through the full RAG pipeline and returns
     * a grounded answer with source citations.
     *
     * @param request chat request containing the user question
     * @return answer generated by the LLM with source metadata
     */
    ChatResponse chat(ChatRequest request);
}
